      as_VIS H sx msF = MS (mkR (Z_to_bv 64 APA_RET_PV) (wz sp') gp tp x5 x6 x7 a0 (Z_to_bv 64 32) a0 (Z_to_bv 64 q) (Z_to_bv 64 0) (Z_to_bv 64 0) (wz 0) (wz 0) (wz 0) xa7
